-// A falsy response retains the current Store object after await. Holding a
-// Store-wide Ref would prevent unrelated writes and balance replacement.
-pub async fn fetch_balance<F, Fut>(
-    store: &dyn safe_cex_store::Store,
+// A falsy response returns the current Store balance by reference, not a copy.
+enum BalanceRead<'a> {
+    Stored(std::cell::Ref<'a, safe_cex_types::Balance>),
+    Parsed(safe_cex_types::Balance),
+}
+impl std::ops::Deref for BalanceRead<'_> {
+    type Target = safe_cex_types::Balance;
+    fn deref(&self) -> &Self::Target {
+        match self {
+            Self::Stored(balance) => balance,
+            Self::Parsed(balance) => balance,
+        }
+    }
+}
+
+pub async fn fetch_balance<'a, F, Fut>(
+    store: &'a dyn safe_cex_store::Store,
     fetch_account: F,
-) -> Result<std::sync::Arc<safe_cex_types::Balance>, ExchangeError>
+) -> Result<impl std::ops::Deref<Target = safe_cex_types::Balance> + 'a, ExchangeError>
 where
     F: FnOnce() -> Fut,
     Fut: Future<Output = Result<Option<Value>, ExchangeError>>,
 {
     let data = fetch_account().await?;
-    let stored = store.balance_handle();
+    let stored = store.balance();
     let parsed = crate::balance::parse_balance(data.as_ref(), &stored).map_err(|error| {
         let mut result = ExchangeError::new(error.message);
         result.name = error.name.into();
         result
     })?;
     Ok(match parsed {
-        std::borrow::Cow::Owned(balance) => std::sync::Arc::new(balance),
-        std::borrow::Cow::Borrowed(_) => stored,
+        std::borrow::Cow::Owned(balance) => BalanceRead::Parsed(balance),
+        std::borrow::Cow::Borrowed(_) => BalanceRead::Stored(stored),
     })
 }
